/// <summary>
/// MPJ_13564_AutoGeneratePaym
/// Service class to run the update and creation of new record
/// </summary>
public class METVendAutoGeneratePaymService extends SysOperationServiceBase
{

}

Method.Source:
    /// <summary>
    /// MPJ_13564_AutoGeneratePaym
    /// Checks if run in batch or not.
    /// </summary>
    /// <param name = "_dataContract">Data contract</param>
    public void processOperation(METVendAutoGeneratePaymContract _dataContract)
    {        
        METVendSumForPaym       vendSumForPaym;
        LedgerJournalTable      ledgerJournalTable;
        ledgerJournalTrans      ledgerJournalTrans;

        List                    journalNumList = new List(Types::String);
        ListEnumerator          enumerator;
        LedgerJournalCheckPost  jourPost;

        QueryRun        qr = new QueryRun(queryStr(METVendAutoGeneratePayments));

        while (qr.next())
        {
            ledgerJournalTrans  =   qr.get(tableNum(LedgerJournalTrans));

            vendSumForPaym = new METVendSumForPaym();
            vendSumForPaym = METVendSumForPaym::newLedgerJournalTrans(ledgerJournalTrans);
            vendSumForPaym.init();
            vendSumForPaym.parmPaymMode(ledgerJournalTrans.PaymMode);
            vendSumForPaym.parmBankAccountID(this.getDisplayValue(ledgerJournalTrans.OffsetLedgerDimension));
            vendSumForPaym.runOperation();

            //Do not post METPAY journals
            if (ledgerJournalTrans.PaymMode != VendParameters::find().METPayPaymMode)
            {
                journalNumList.addStart(ledgerJournalTrans.JournalNum);
            }

        }

        enumerator = journalNumList.getEnumerator();

        while (enumerator.moveNext())
        {
            ledgerJournalTable = LedgerJournalTable::find(enumerator.current());
            jourPost = LedgerJournalCheckPost::newLedgerJournalTable(ledgerJournalTable, NoYes::Yes);
            jourPost.runOperation();
        }
        
    }

    /// <summary>
    /// Gets dynamic account value
    /// </summary>
    /// <param name = "_dimensionDynamicAccount">dimension recid</param>
    /// <returns>display value</returns>
    public str getDisplayValue(DimensionDynamicAccount _dimensionDynamicAccount)
    {
        DimensionAttributeValueCombination dimensionAttributeValueCombination;

        select firstonly
            displayValue
        from
            dimensionAttributeValueCombination
        where
            dimensionAttributeValueCombination.RecId == _dimensionDynamicAccount;

        return dimensionAttributeValueCombination.DisplayValue;
    }
